mapper.select:
SELECT sa.*, sa.project_id AS 'project.id', cp.`name` AS 'project.name', cp.`short_name` AS 'project.short_name', cp.`serial_number` AS 'project.serial_number', sa.monomer_id 'monomer.id', m.name 'monomer.name', sa.area_id 'area.id', ar.name 'area.name', u.name AS user_name, a.NAME, a.serial_number, a.material, a.quantity, a.length, a.net_weight, a.total_net_weight FROM tech_artifact_spec_amend sa INNER JOIN tech_artifact_record a ON sa.artifact_id = a.id AND a.bool_delete_enum = 0 LEFT JOIN mes_tech_inventory_operation operation on operation.id = a.inventory_operation_id and operation.bool_delete_enum =0 LEFT JOIN contract_project cp ON sa.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer m ON sa.monomer_id = m.id AND m.bool_delete_enum = 0 LEFT JOIN plan_area ar ON sa.area_id = ar.id AND ar.bool_delete_enum = 0 LEFT JOIN sys_user u ON sa.user_id = u.id AND u.bool_delete_enum = 0 WHERE sa.bool_delete_enum = 0 and operation.inventory_reviewed_enum not in (4,16)
AND sa.project_id = #{projectId}
AND sa.monomer_id = #{monomerId}
AND sa.area_id = #{areaId}
AND sa.old_specification like concat('%', #{oldSpecification}, '%')
AND sa.new_specification like concat('%', #{newSpecification}, '%')
AND sa.old_specification = #{specification}
AND sa.bool_amend_status = #{boolAmendStatus}
AND a.name like concat('%', #{name}, '%')
AND a.serial_number like concat('%', #{serialNumber}, '%')

SELECT *, 0 AS plJudge FROM tech_artifact_spec_amend WHERE bool_delete_enum = FALSE AND inventory_operation_id = #{inventoryOperationId} and bool_amend_status = false
AND serial_number like concat('%', #{serialNumber}, '%')
AND old_specification like concat('%', #{specification}, '%')
AND material like concat('%', #{material}, '%')
AND length >= #{minLength}
AND length <= #{maxLength}
AND new_structure_class_id = #{structureClassId}
order by new_specification
order by old_specification
